declare(strict_types=1); require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/includes/auth.php';
$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');
if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='delete'&&$id){db()->prepare('DELETE FROM projects WHERE id=?')->execute([$id]);header('Location: projects.php');exit;}if($action==='toggle'&&$id){db()->prepare('UPDATE projects SET is_published=1-COALESCE(is_published,0) WHERE id=?')->execute([$id]);header('Location: projects.php');exit;}}
$projects=db()->query('SELECT * FROM projects ORDER BY COALESCE(is_featured,0) DESC, created_at DESC')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Projects | Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container"><a class="navbar-brand" href="dashboard.php">Distinguished Web Services</a><a class="btn btn-outline-light btn-sm" href="logout.php">Logout</a></div></nav><main class="container py-5"><div class="d-flex justify-content-between align-items-center mb-4"><h1 class="h2">Projects</h1><a href="project-form.php" class="btn btn-primary">Add Project</a></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Project</th><th>Category</th><th>Featured</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($projects as $p): ?><tr><td><strong><?=$esc($p['title']??'')?></strong><div class="small text-muted"><?=$esc($p['slug']??'')?></div></td><td><?=$esc($p['category']??'')?></td><td><?=((int)($p['is_featured']??0)?'Yes':'No')?></td><td><span class="badge <?=((int)($p['is_published']??0)?'text-bg-success':'text-bg-secondary')?>"><?=((int)($p['is_published']??0)?'Published':'Draft')?></span></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="project-form.php?id=<?=((int)($p['id']??0))?>">Edit</a><form method="post" class="d-inline"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=((int)($p['id']??0))?>"><button class="btn btn-sm btn-outline-secondary">Toggle</button></form><form method="post" class="d-inline" onsubmit="return confirm('Delete this project?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=((int)($p['id']??0))?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;if(!$projects):?><tr><td colspan="5" class="text-center text-muted py-5">No projects yet.</td></tr><?php endif;?></tbody></table></div></div></main></body></html>